DIRS = ["up", "right", "down", "left"]

def magnitude(value):
    if value < 0:
        return -value
    return value

def smaller(left, right):
    if left < right:
        return left
    return right

def make_graph(board, width):
    graph = {}
    offsets = [-width, 1, width, -1]
    for y in range(1, len(board) - 1):
        for x in range(1, width - 1):
            if board[y][x] != ".":
                continue
            cell = y * width + x
            edges = []
            for direction in range(4):
                neighbor = cell + offsets[direction]
                if board[neighbor // width][neighbor % width] == ".":
                    edges.append([neighbor, DIRS[direction]])
            graph[cell] = edges
    return graph

def route_table(graph, cache, start):
    if start in cache:
        return cache[start]
    table = {start: [0, None]}
    queue = [start]
    for cell in queue:
        previous = table[cell]
        for edge in graph[cell]:
            neighbor = edge[0]
            if neighbor in table:
                continue
            first = previous[1]
            if first is None:
                first = edge[1]
            table[neighbor] = [previous[0] + 1, first]
            queue.append(neighbor)
    cache[start] = table
    return table

def choose(state, graph, cache):
    board = state["tiles"]
    width = len(board[0])
    player = state["player"]
    start = player[1] * width + player[0]
    rivals = state["opponents"]
    own_routes = route_table(graph, cache, start)
    best_merit = -100000
    action = "wait"
    for item in state["items"]:
        cell = item["y"] * width + item["x"]
        if cell == start:
            return "pick"
        if cell not in own_routes:
            continue
        distance = own_routes[cell][0]
        direction = own_routes[cell][1]
        safety = 4
        for index in range(len(rivals)):
            rival = rivals[index]
            remaining = magnitude(item["x"] - rival["x"]) + magnitude(item["y"] - rival["y"])
            if remaining < distance:
                safety = smaller(safety, 0)
            elif remaining == distance:
                priority = (state["turn"] + distance) % (len(rivals) + 1)
                if priority > 0 and index + 1 >= priority:
                    safety = smaller(safety, 1)
                else:
                    safety = smaller(safety, 3)
        merit = safety * 20 - distance * 8
        if merit > best_merit:
            action = direction
            best_merit = merit
    return action
board = []
while True:
    state = scan()
    if state["tiles"] != board:
        board = state["tiles"]
        graph = make_graph(board, len(board[0]))
        cache = {}
    action = choose(state, graph, cache)
    if action == "pick":
        pick()
    elif action == "wait":
        wait()
    else:
        move(action)

